            bin_weight = math.fsum(w_terms)
            pos_weight = math.fsum(pos_terms)
            prob_weight = math.fsum(wp_terms)
        except (OverflowError, ValueError) as exc:
            raise FloatingPointError(
                "non-finite value encountered during calibration "
                "computation"
            ) from exc
